 OR (a.reason IN ('tenant_reference_review_required','producer_drain_required','queue_cleanup_failed','object_cleanup_failed','database_cleanup_failed') AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'='{"source":"tenant_erasure"}'::jsonb)))
 OR (a.action='tenant.deleted' AND a.reason IS NULL AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'='{"source":"tenant_erasure","online_content_erased":true,"retained":["ownership_binding","budget_ledger","erasure_receipt"],"external_backup_retention":"operator_policy"}'::jsonb)
 OR (a.action='tenant.updated' AND a.reason IS NULL AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'source'='tenant_erasure_runtime_cleanup' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via' - ARRAY['source','revisions','secret_versions','restart_requests','pending_bindings']='{}'::jsonb AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'revisions' ~ '^[0-9]{1,10}$' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'secret_versions' ~ '^[0-9]{1,10}$' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'restart_requests' ~ '^[0-9]{1,10}$' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'pending_bindings' ~ '^[0-9]{1,10}$')
 ))
 OR (a.resource_type='hosted_work' AND a.action='hosted_work.reconciled' AND a.reason='operator_reviewed_owner_stop' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via' - ARRAY['owner_boot_id','evidence_sha256','operator_tenant_id']='{}'::jsonb AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'owner_boot_id' ~ '^[0-9a-f-]{36}$' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'operator_tenant_id' ~ '^[0-9a-f-]{36}$' AND (CASE WHEN subkit.hosted_audit_metadata_without_provenance(a.metadata)->>'via'='token_exchange' THEN subkit.hosted_audit_metadata_without_provenance(a.metadata)-'via' ELSE subkit.hosted_audit_metadata_without_provenance(a.metadata) END)-'auth_via'->>'evidence_sha256' ~ '^[0-9a-f]{64}$')
 ))),false)
 GROUP BY a.tenant_id
)
SELECT subkit.hosted_apply_usage(tenant_id,'audit_log',-row_bytes,-row_count) FROM newly_exempt;
